"""Simple DPLL SAT solver with unit propagation and pure literal elimination."""
from typing import List

def solve_sat(instance) -> bool:
    m = instance["num_vars"]
    clauses = [list(c) for c in instance["clauses"]]
    # empty clause -> unsat
    if any(len(c) == 0 for c in clauses):
        return False
    # assignment: var -> True/False
    assign = {}
    return _dpll(clauses, assign, m)

def _simplify(clauses, assign):
    """Return simplified clauses or None if conflict."""
    new = []
    for c in clauses:
        sat = False
        lits = []
        for lit in c:
            v = abs(lit)
            val = (lit > 0)
            if v in assign:
                if assign[v] == val:
                    sat = True
                    break
            else:
                lits.append(lit)
        if sat:
            continue
        if not lits:
            return None  # conflict
        new.append(lits)
    return new

def _unit_propagate(clauses, assign):
    while True:
        unit = None
        for c in clauses:
            if len(c) == 1:
                unit = c[0]
                break
        if unit is None:
            return clauses, assign
        v = abs(unit)
        val = (unit > 0)
        if v in assign:
            if assign[v] != val:
                return None, None
            # remove satisfied
            clauses = [c for c in clauses if not (len(c)==1 and abs(c[0])==v)]
            continue
        assign[v] = val
        clauses = _simplify(clauses, assign)
        if clauses is None:
            return None, None

def _dpll(clauses, assign, m):
    res = _unit_propagate(clauses, assign)
    if res == (None, None):
        return False
    clauses, assign = res
    if not clauses:
        return True
    # pure literal elimination
    pos = set(); neg = set()
    for c in clauses:
        for lit in c:
            (pos if lit > 0 else neg).add(abs(lit))
    pure = (pos - neg)
    pure_neg = (neg - pos)
    if pure or pure_neg:
        new_assign = dict(assign)
        for v in pure:
            new_assign[v] = True
        for v in pure_neg:
            new_assign[v] = False
        nc = _simplify(clauses, new_assign)
        if nc is None:
            return False
        return _dpll(nc, new_assign, m)
    # choose variable with most occurrences
    counts = {}
    for c in clauses:
        for lit in c:
            counts[abs(lit)] = counts.get(abs(lit), 0) + 1
    v = max(counts, key=counts.get)
    for val in (True, False):
        na = dict(assign); na[v] = val
        nc = _simplify(clauses, na)
        if nc is None:
            continue
        if _dpll(nc, na, m):
            return True
    return False
